mapper.insert:
insert into community (
community_content, file_path, created_at, updated_at, community_view_count, community_like_count, community_reply_count, community_deleted, user_no)
values (#{communityContent}, #{filePath}, current_timestamp, #{updatedAt}, #{communityViewCount}, #{communityLikeCount}, #{communityReplyCount}, #{communityDeleted}, 1);
